-- Spec §5.2 (OMS) and §7.2 (edits). Object tables in schema "obj" are generated by OMS / `ontoctl ddl`.
CREATE SCHEMA IF NOT EXISTS oms;
CREATE SCHEMA IF NOT EXISTS edits;
CREATE SCHEMA IF NOT EXISTS obj;

CREATE TABLE oms.ontology (
  api_name       TEXT PRIMARY KEY,
  display_name   TEXT NOT NULL,
  active_version BIGINT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE oms.ontology_version (
  ontology       TEXT   NOT NULL REFERENCES oms.ontology(api_name),
  version        BIGINT NOT NULL,
  git_commit     TEXT   NOT NULL,
  checksum       TEXT   NOT NULL,
  compiled       JSONB  NOT NULL,
  changeset      JSONB  NOT NULL,
  status         TEXT   NOT NULL CHECK (status IN ('PENDING','ACTIVE','SUPERSEDED','FAILED','ROLLED_BACK')),
  published_by   TEXT   NOT NULL,
  published_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  ddl_applied_at TIMESTAMPTZ,
  error          JSONB,
  PRIMARY KEY (ontology, version),
  UNIQUE (ontology, checksum)
);

CREATE TABLE oms.type_registry (
  ontology      TEXT NOT NULL,
  kind          TEXT NOT NULL CHECK (kind IN ('object-type','link-type','action-type','value-type')),
  api_name      TEXT NOT NULL,
  rid           TEXT NOT NULL UNIQUE,
  first_version BIGINT NOT NULL,
  last_version  BIGINT,
  PRIMARY KEY (ontology, kind, api_name)
);

CREATE TABLE edits.action_run (
  action_rid      TEXT PRIMARY KEY,
  ontology        TEXT NOT NULL,
  ontology_ver    BIGINT NOT NULL,
  action_type     TEXT NOT NULL,
  actor_id        TEXT NOT NULL,
  actor_kind      TEXT NOT NULL CHECK (actor_kind IN ('USER','AGENT','SERVICE')),
  on_behalf_of    TEXT,
  idempotency_key TEXT,
  request_hash    TEXT NOT NULL,
  parameters      JSONB NOT NULL,
  status          TEXT NOT NULL CHECK (status IN
                  ('RECEIVED','VALIDATED','WRITEBACK_PENDING','COMMITTED','FAILED','COMPENSATING','COMPENSATED')),
  result          JSONB,
  error           JSONB,
  workflow_id     TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  committed_at    TIMESTAMPTZ
);
CREATE UNIQUE INDEX action_run_idem ON edits.action_run (actor_id, action_type, idempotency_key)
  WHERE idempotency_key IS NOT NULL;
CREATE INDEX action_run_status ON edits.action_run (status, updated_at);

CREATE TABLE edits.object_edit (
  edit_id     BIGSERIAL PRIMARY KEY,
  action_rid  TEXT NOT NULL REFERENCES edits.action_run,
  object_type TEXT NOT NULL,
  object_pk   TEXT NOT NULL,
  op          TEXT NOT NULL CHECK (op IN ('CREATE','MODIFY','DELETE','LINK','UNLINK')),
  changes     JSONB NOT NULL,
  before      JSONB,
  link_type   TEXT,
  edit_ts     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX object_edit_obj ON edits.object_edit (object_type, object_pk, edit_id);

CREATE TABLE edits.outbox (
  id           BIGSERIAL PRIMARY KEY,
  aggregate    TEXT NOT NULL,
  aggregate_id TEXT NOT NULL,
  event_type   TEXT NOT NULL,
  payload      JSONB NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE edits.side_effect_run (
  id          BIGSERIAL PRIMARY KEY,
  action_rid  TEXT NOT NULL REFERENCES edits.action_run,
  kind        TEXT NOT NULL,
  name        TEXT NOT NULL,
  mode        TEXT NOT NULL CHECK (mode IN ('WRITEBACK','SIDE_EFFECT','COMPENSATE')),
  attempt     INT  NOT NULL DEFAULT 0,
  status      TEXT NOT NULL CHECK (status IN ('PENDING','SUCCEEDED','FAILED')),
  request     JSONB,
  response    JSONB,
  error       JSONB,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (action_rid, name, mode)
);
